cat > bot.mjs <<'EOF'
// Notification gate: consent, quiet hours 22:00-08:00 local, 3 per local day.
// Also: whyNotReceived (support log) and dryRun (policy replay, touches no state).

const QUIET_START = "22:00";
const QUIET_END = "08:00";
const DAILY_CAP = 3;

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  gkFs.mkdirSync(dir, { recursive: true });
  return dir;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function logFile(dir, userId) {
  return gkPathFor(dir, `log:${userId}`, ".jsonl");
}

function appendLog(dir, entry) {
  // One O_APPEND write of a short line: safe across worker processes.
  gkFs.appendFileSync(logFile(dir, entry.userId), JSON.stringify(entry) + "\n");
}

function capKey(userId, zone, ms) {
  return `cap:${userId}:${gkDayKey(ms, zone)}`;
}

function capFull(dir, userId, zone, ms) {
  const rec = gkRead(dir, `capview:${userId}:${gkDayKey(ms, zone)}`);
  return rec ? rec.n >= DAILY_CAP : false;
}

// Earliest instant a notification held at ms could pass quiet hours and the cap.
function availableAfter(dir, userId, zone, ms) {
  let t = gkNextOpen(ms, zone, QUIET_END, QUIET_START);
  for (let i = 0; i < 4 && t !== null && capFull(dir, userId, zone, t); i += 1) {
    t = gkNextOpen(gkNextMidnight(t, zone), zone, QUIET_END, QUIET_START);
  }
  return t;
}

function heldText(code, zone, availableMs) {
  const when = availableMs == null ? "" : ` It could have been delivered from ${gkFmt(availableMs, zone)}.`;
  if (code === "NO_CONSENT") return "It was not delivered because you have not agreed to receive notifications.";
  if (code === "INVALID_TIMEZONE") return "It was not delivered because we have no valid time zone for your account, so we could not check your quiet hours.";
  if (code === "QUIET_HOURS") return `It was not delivered because it arrived during quiet hours (${QUIET_START} to ${QUIET_END} your local time).${when}`;
  return `It was not delivered because you had already received the limit of ${DAILY_CAP} notifications that local day.${when}`;
}

function record(dir, user, notification, ms, delivered, code, availableMs) {
  const zoneOk = gkZoneOk(user.timezone);
  appendLog(dir, {
    userId: user.id,
    notificationId: notification.id,
    atMs: ms,
    delivered,
    ruleCode: code,
    availableMs: availableMs ?? null,
    zone: zoneOk ? user.timezone : null,
  });
}

export async function decide({ user, notification, now }) {
  const dir = stateDir();
  const ms = now.getTime();
  const idKey = `sent:${user.id}:${notification.id}`;
  for (;;) {
    if (gkClaim(dir, idKey)) break;
    // Another call owns this id: wait for its outcome.
    for (let i = 0; i < 100; i += 1) {
      if (gkRead(dir, idKey)) return { send: true };
      if (!gkFs.existsSync(gkPathFor(dir, idKey, ".claim"))) break;
      await sleep(20);
    }
    if (gkRead(dir, idKey)) return { send: true };
    if (gkFs.existsSync(gkPathFor(dir, idKey, ".claim"))) return { send: false }; // owner outcome unknown
  }
  let code = null;
  let availableMs = null;
  let capCounted = false;
  if (user.consent !== true) code = "NO_CONSENT";
  else if (!gkZoneOk(user.timezone)) code = "INVALID_TIMEZONE";
  else if (gkInWindow(ms, user.timezone, QUIET_START, QUIET_END)) code = "QUIET_HOURS";
  else {
    const c = gkCount(dir, capKey(user.id, user.timezone, ms), DAILY_CAP);
    if (!c.ok) code = "DAILY_CAP";
    else {
      capCounted = true;
      gkWrite(dir, `capview:${user.id}:${gkDayKey(ms, user.timezone)}`, { n: c.n });
    }
  }
  if (code === null) {
    gkWrite(dir, idKey, { at: ms });
    record(dir, user, notification, ms, true, null, null);
    return { send: true };
  }
  if (code === "QUIET_HOURS") availableMs = availableAfter(dir, user.id, user.timezone, ms);
  else if (code === "DAILY_CAP") availableMs = availableAfter(dir, user.id, user.timezone, gkNextMidnight(ms, user.timezone));
  record(dir, user, notification, ms, false, code, availableMs);
  gkUnclaim(dir, idKey); // refused: nothing left, a later retry may pass
  return { send: false };
}

export async function whyNotReceived({ userId, from, to }) {
  const dir = stateDir();
  const f = Date.parse(from);
  const t = Date.parse(to);
  let raw = "";
  try {
    raw = gkFs.readFileSync(logFile(dir, userId), "utf8");
  } catch (e) {
    if (e.code !== "ENOENT") throw e;
  }
  const out = [];
  for (const line of raw.split("\n")) {
    if (!line) continue;
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    if (e.atMs < f || e.atMs >= t) continue;
    let text;
    if (e.delivered) {
      text = e.zone ? `It was delivered at ${gkFmt(e.atMs, e.zone)}.` : "It was delivered.";
    } else {
      // Recompute the retry time now so a cap/quiet answer reflects current counts.
      text = heldText(e.ruleCode, e.zone, e.availableMs);
    }
    out.push({
      notificationId: e.notificationId,
      at: new Date(e.atMs).toISOString(),
      delivered: e.delivered,
      ruleCode: e.ruleCode,
      availableAt: e.availableMs == null ? null : new Date(e.availableMs).toISOString(),
      text,
    });
  }
  return out;
}

export async function dryRun({ events, policy }) {
  const qh = policy?.quietHours ?? null;
  const cap = policy?.dailyCap ?? null;
  const ordered = events
    .map((ev, i) => ({ ev, i, ms: Date.parse(ev.at) }))
    .sort((a, b) => a.ms - b.ms || a.i - b.i);
  const counts = new Map(); // in memory only
  const seen = new Set();
  let delivered = 0;
  let blocked = 0;
  for (const { ev, ms } of ordered) {
    const { user, notification } = ev;
    const idKey = `${user.id}\u0000${notification.id}`;
    if (seen.has(idKey)) continue; // redelivery of the same notification: not a new event
    seen.add(idKey);
    if (user.consent !== true || !gkZoneOk(user.timezone) || Number.isNaN(ms)) { blocked += 1; continue; }
    if (qh && gkInWindow(ms, user.timezone, qh.start, qh.end)) { blocked += 1; continue; }
    if (cap !== null) {
      const k = `${user.id}\u0000${gkDayKey(ms, user.timezone)}`;
      const n = counts.get(k) ?? 0;
      if (n >= cap) { blocked += 1; continue; }
      counts.set(k, n + 1);
    }
    delivered += 1;
  }
  return { delivered, blocked };
}
